// Headed Chrome CDP harness for Meridian release validation.
// Uses Node's global WebSocket (Node 22+) to speak the DevTools Protocol.
import { spawn } from "node:child_process";
import { setTimeout as sleep } from "node:timers/promises";
import http from "node:http";

const CHROME = process.env.CHROME_BIN;
const PORT = Number(process.env.CDP_PORT || "9333");
const PROFILE = process.env.PROFILE_DIR;
const EXT = process.env.EXT_DIR;

function httpJson(path) {
  return new Promise((resolve, reject) => {
    http.get({ host: "127.0.0.1", port: PORT, path }, (res) => {
      let d = "";
      res.on("data", (c) => (d += c));
      res.on("end", () => {
        try { resolve(JSON.parse(d)); } catch (e) { resolve(d); }
      });
    }).on("error", reject);
  });
}

class CDP {
  constructor(wsUrl) { this.ws = null; this.id = 0; this.pending = new Map(); this.events = []; this.wsUrl = wsUrl; }
  connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.wsUrl);
      this.ws.onopen = () => resolve();
      this.ws.onerror = (e) => reject(new Error("ws error " + (e.message || "")));
      this.ws.onmessage = (m) => {
        const msg = JSON.parse(m.data);
        if (msg.id && this.pending.has(msg.id)) {
          const { resolve, reject } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          if (msg.error) reject(new Error(JSON.stringify(msg.error)));
          else resolve(msg.result);
        } else if (msg.method) {
          this.events.push(msg);
        }
      };
    });
  }
  send(method, params = {}, sessionId) {
    const id = ++this.id;
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = id && sessionId;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      // attach sessionId at top level for flat protocol
      const wire = sessionId ? { id, method, params, sessionId } : { id, method, params };
      this.ws.send(JSON.stringify(wire));
      setTimeout(() => { if (this.pending.has(id)) { this.pending.delete(id); reject(new Error("timeout " + method)); } }, 20000);
    });
  }
  close() { try { this.ws.close(); } catch {} }
}

const result = { steps: [], errors: [], warnings: [], targets: [] };
function log(k, v) { result.steps.push({ k, v }); console.error(`[harness] ${k}: ${typeof v === "object" ? JSON.stringify(v) : v}`); }

let chromeProc;
try {
  chromeProc = spawn(CHROME, [
    `--remote-debugging-port=${PORT}`,
    `--user-data-dir=${PROFILE}`,
    `--no-first-run`, `--no-default-browser-check`,
    `--disable-extensions-except=${EXT}`,
    `--load-extension=${EXT}`,
    `--enable-unsafe-extension-debugging`,
    `--remote-debugging-pipe=false`,
    `about:blank`,
  ], { stdio: "ignore" });
  log("chrome_pid", chromeProc.pid);

  // wait for CDP endpoint
  let version = null;
  for (let i = 0; i < 40; i++) {
    try { version = await httpJson("/json/version"); if (version && version.webSocketDebuggerUrl) break; } catch {}
    await sleep(500);
  }
  if (!version || !version.webSocketDebuggerUrl) throw new Error("CDP endpoint never came up");
  log("browser", version.Browser);

  const browser = new CDP(version.webSocketDebuggerUrl);
  await browser.connect();
  await browser.send("Target.setDiscoverTargets", { discover: true });
  await sleep(1500);

  // give the extension SW time to register
  let targets = [];
  let extId = null;
  for (let i = 0; i < 20; i++) {
    const r = await browser.send("Target.getTargets", {});
    targets = r.targetInfos;
    const sw = targets.find((t) => t.type === "service_worker" && t.url.startsWith("chrome-extension://"));
    if (sw) { extId = sw.url.split("/")[2]; break; }
    await sleep(500);
  }
  result.targets = targets.map((t) => ({ type: t.type, url: t.url.slice(0, 90) }));
  log("extension_id", extId);
  log("target_count", targets.length);

  // Open the New Tab (meridian.html) directly to validate the override page
  if (extId) {
    const ntUrl = `chrome-extension://${extId}/meridian.html`;
    const created = await browser.send("Target.createTarget", { url: ntUrl });
    await sleep(2500);
    // attach to the new tab
    const att = await browser.send("Target.attachToTarget", { targetId: created.targetId, flatten: true });
    const session = att.sessionId;
    await browser.send("Runtime.enable", {}, session);
    await browser.send("Log.enable", {}, session);
    await browser.send("Page.enable", {}, session);
    await sleep(1500);

    // collect console/log/exception events for this session
    const sessionEvents = browser.events.filter((e) => e.sessionId === session);
    const consoleErrors = sessionEvents.filter((e) => e.method === "Runtime.consoleAPICalled" && (e.params.type === "error"));
    const logErrors = sessionEvents.filter((e) => e.method === "Log.entryAdded" && e.params.entry.level === "error");
    const exceptions = sessionEvents.filter((e) => e.method === "Runtime.exceptionThrown");
    const logWarnings = sessionEvents.filter((e) => e.method === "Log.entryAdded" && e.params.entry.level === "warning");

    async function evalIn(expr) {
      const r = await browser.send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true }, session);
      if (r.exceptionDetails) return { error: r.exceptionDetails.text || JSON.stringify(r.exceptionDetails) };
      return r.result.value;
    }

    const dom = await evalIn(`(function(){
      const q = (s)=>document.querySelector(s);
      const combo = document.querySelector('[role="combobox"]') || document.querySelector('input');
      return {
        title: document.title,
        hasCombobox: !!document.querySelector('[role="combobox"]'),
        comboRole: combo ? combo.getAttribute('role') : null,
        ariaExpanded: combo ? combo.getAttribute('aria-expanded') : null,
        inputCount: document.querySelectorAll('input').length,
        buttonCount: document.querySelectorAll('button').length,
        tabCardCount: document.querySelectorAll('[class*="card"],[data-tab-id],.tab-card').length,
        bodyTextLen: (document.body.innerText||'').length,
        hasSettings: /settings/i.test(document.body.innerHTML),
        readyState: document.readyState,
      };
    })()`);
    log("newtab_dom", dom);
    result.newtabDom = dom;
    result.consoleErrors = consoleErrors.map((e) => (e.params.args||[]).map(a=>a.value||a.description).join(" "));
    result.logErrors = logErrors.map((e) => e.params.entry.text);
    result.exceptions = exceptions.map((e) => e.params.exceptionDetails.text + " " + (e.params.exceptionDetails.exception?.description||""));
    result.logWarnings = logWarnings.map((e) => e.params.entry.text).slice(0, 20);
    log("console_errors", result.consoleErrors.length);
    log("log_errors", result.logErrors.length);
    log("exceptions", result.exceptions.length);
    log("log_warnings", result.logWarnings.length);

    // Inspect the service worker for errors too
    const sw = targets.find((t) => t.type === "service_worker" && t.url.includes(extId));
    if (sw) {
      try {
        const swAtt = await browser.send("Target.attachToTarget", { targetId: sw.targetId, flatten: true });
        const swSession = swAtt.sessionId;
        await browser.send("Runtime.enable", {}, swSession);
        await browser.send("Log.enable", {}, swSession);
        await sleep(1000);
        const swEvents = browser.events.filter((e) => e.sessionId === swSession);
        result.swConsoleErrors = swEvents.filter((e) => e.method === "Runtime.consoleAPICalled" && e.params.type === "error").length;
        result.swExceptions = swEvents.filter((e) => e.method === "Runtime.exceptionThrown").length;
        const swEval = await browser.send("Runtime.evaluate", { expression: "typeof chrome !== 'undefined' && typeof chrome.tabs !== 'undefined'", returnByValue: true }, swSession);
        result.swHasChromeTabs = swEval.result.value;
        log("sw_console_errors", result.swConsoleErrors);
        log("sw_exceptions", result.swExceptions);
        log("sw_has_chrome_tabs", result.swHasChromeTabs);
      } catch (e) { log("sw_inspect_error", e.message); }
    }
  }

  browser.close();
} catch (e) {
  result.fatal = e.message;
  console.error("[harness] FATAL", e.message);
} finally {
  if (chromeProc) { try { chromeProc.kill(); } catch {} }
  await sleep(500);
  console.log(JSON.stringify(result, null, 2));
}

