    out.swExceptions=sev.filter(e=>e.method==="Runtime.exceptionThrown").length;
    const swapi=await b.send("Runtime.evaluate",{expression:"({tabs:typeof chrome.tabs,groups:typeof chrome.tabGroups,storage:typeof chrome.storage,sidePanel:typeof chrome.sidePanel})",returnByValue:true},ss);
