import http from "node:http";
const PORT = Number(process.env.CDP_PORT || "9336");
const EXT = process.env.EXT_DIR;
function httpJson(path){return new Promise((res,rej)=>{http.get({host:"127.0.0.1",port:PORT,path},r=>{let d="";r.on("data",c=>d+=c);r.on("end",()=>{try{res(JSON.parse(d))}catch{res(d)}})}).on("error",rej)})}
class CDP{constructor(u){this.ws=null;this.id=0;this.p=new Map();this.events=[];this.u=u}
 connect(){return new Promise((rs,rj)=>{this.ws=new WebSocket(this.u);this.ws.onopen=()=>rs();this.ws.onerror=e=>rj(new Error("ws"));this.ws.onmessage=m=>{const x=JSON.parse(m.data);if(x.id&&this.p.has(x.id)){const{resolve,reject}=this.p.get(x.id);this.p.delete(x.id);x.error?reject(new Error(JSON.stringify(x.error))):resolve(x.result)}else if(x.method)this.events.push(x)}})}
 send(method,params={},sessionId){const id=++this.id;return new Promise((rs,rj)=>{this.p.set(id,{resolve:rs,reject:rj});this.ws.send(JSON.stringify(sessionId?{id,method,params,sessionId}:{id,method,params}));setTimeout(()=>{if(this.p.has(id)){this.p.delete(id);rj(new Error("timeout "+method))}},15000)})}}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const out={ok:true};
const v=await httpJson("/json/version");
const b=new CDP(v.webSocketDebuggerUrl);await b.connect();
out.browser=v.Browser;
const lr=await b.send("Extensions.loadUnpacked",{path:EXT});
const extId=lr.id; out.extId=extId;
await sleep(2000);
await b.send("Target.setDiscoverTargets",{discover:true});
// Open some real tabs (data: URLs the SW can enumerate & capture)
const colors=["f00","0a0","00f","fa0","808","0aa"];
for(const c of colors){ await b.send("Target.createTarget",{url:`data:text/html,<title>Probe ${c}</title><body style='background:%23${c}'>Probe ${c}`}); }
await sleep(1500);
// Open the New Tab page
const nt=await b.send("Target.createTarget",{url:`chrome-extension://${extId}/meridian.html`});
await sleep(3500);
const att=await b.send("Target.attachToTarget",{targetId:nt.targetId,flatten:true});const s=att.sessionId;
await b.send("Runtime.enable",{},s);await b.send("Log.enable",{},s);await b.send("Page.enable",{},s);await b.send("Network.enable",{},s);
await sleep(1500);
async function ev(expr){const r=await b.send("Runtime.evaluate",{expression:expr,returnByValue:true,awaitPromise:true},s);return r.exceptionDetails?{__err:(r.exceptionDetails.exception?.description||r.exceptionDetails.text)}:r.result.value;}

// A11y / initial DOM
out.initial=await ev(`(()=>{const c=document.querySelector('[role=combobox]');return{combobox:!!c,controls:c?.getAttribute('aria-controls'),expanded:c?.getAttribute('aria-expanded'),cards:document.querySelectorAll('.tab-card,[data-tab-id],[class*=card]').length,settingsBtn:!!document.getElementById('settings-btn')}})()`);

// SEARCH + keyboard nav + aria-activedescendant
out.searchNav=await ev(`(async()=>{
  const input=document.querySelector('[role=combobox]');
  input.focus(); input.value='probe';
  input.dispatchEvent(new Event('input',{bubbles:true}));
  input.dispatchEvent(new KeyboardEvent('keydown',{key:'probe',bubbles:true}));
  await new Promise(r=>setTimeout(r,900));
  const listbox=document.getElementById('browser-search-results');
  const before={listbox:!!listbox, visible: listbox? getComputedStyle(listbox).display!=='none':false, expanded:input.getAttribute('aria-expanded'), options:document.querySelectorAll('#browser-search-results [role=option]').length, groups:document.querySelectorAll('#browser-search-results [role=group]').length};
  input.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true}));
  await new Promise(r=>setTimeout(r,250));
  const ad=input.getAttribute('aria-activedescendant');
  const sel=document.querySelectorAll('#browser-search-results [aria-selected=true]').length;
  return {...before, afterArrow_activedescendant:ad, afterArrow_selectedCount:sel};
})()`);

// ESCAPE clears + collapses
out.escape=await ev(`(async()=>{
  const input=document.querySelector('[role=combobox]');
  input.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
  await new Promise(r=>setTimeout(r,300));
  const listbox=document.getElementById('browser-search-results');
  return {value:input.value, expanded:input.getAttribute('aria-expanded'), activedescendant:input.getAttribute('aria-activedescendant'), resultsClosed: !listbox || getComputedStyle(listbox).display==='none'};
})()`);

// FORMER BLOCKER #1: settings-during-search must keep Settings open and not let pending results reclaim popup
out.blocker1=await ev(`(async()=>{
  const input=document.querySelector('[role=combobox]');
  input.focus(); input.value='probe';
  input.dispatchEvent(new Event('input',{bubbles:true}));
  input.dispatchEvent(new KeyboardEvent('keydown',{key:'e',bubbles:true}));
  await new Promise(r=>setTimeout(r,120));
  const sb=document.getElementById('settings-btn'); sb.click();
  await new Promise(r=>setTimeout(r,1000));
  const settingsOpen = !!document.querySelector('#settings-panel,[data-settings-open],.settings-popup,.settings-panel') || /Privacy & Data|Appearance/.test(document.body.innerText);
  const results=document.getElementById('browser-search-results');
  const resultsVisible = results && getComputedStyle(results).display!=='none' && results.querySelectorAll('[role=option]').length>0;
  return {settingsOpen, resultsReclaimed: !!resultsVisible};
})()`);

// THUMBNAILS: trigger a real refresh via the SW and count thumb_* in storage
out.thumbnails=await ev(`(async()=>{
  const resp=await chrome.runtime.sendMessage({type:'REFRESH_THUMBNAILS'});
  await new Promise(r=>setTimeout(r,1500));
  const all=await chrome.storage.local.get(null);
  const thumbKeys=Object.keys(all).filter(k=>k.startsWith('thumb_'));
  return {refreshResponse:resp, thumbCount:thumbKeys.length};
})()`);

// PERSISTENCE (in-session): write a setting then read back
out.persistence=await ev(`(async()=>{
  await chrome.storage.local.set({__validation_probe:'ok'});
  const r=await chrome.storage.local.get('__validation_probe');
  return {roundtrip:r.__validation_probe==='ok'};
})()`);

await sleep(800);
// Network origins seen from the extension page
